examples:
```cpp
class TextHolder {
public:
    TextHolder(std::string text) : m_text{std::move(text)} {}

    const std::string& getText() const & { return m_text; }
    std::string&& getText() && { return std::move(m_text); }

private:
    std::string m_text;
};

TextHolder textHolder{"Hello world!"};
textHolder.getText();                       // 调用 & 版本
TextHolder{"Hello world!"}.getText();      // 调用 && 版本
std::move(textHolder).getText();            // 调用 && 版本
```
